import React from 'react';
import { render, screen } from '@testing-library/react';
import ProgressMeter from './ProgressMeter';

describe('ProgressMeter', () => {
  it('should render withou crashing', () => {
    render(<ProgressMeter />);
    expect(screen.getByRole('progressbar')).toBeInTheDocument();
  });

  it('should render label withou crashing', () => {
    render(<ProgressMeter label="test" />);
    expect(screen.getByRole('progressbar')).toBeInTheDocument();
    expect(screen.getByText('test')).toBeInTheDocument();
  });

  it('should render with same value in maxValue and Value props without crashing', () => {
    render(<ProgressMeter label="test" maxValue={100} value={100} />);
    expect(screen.getByTestId('Checkmark2')).toBeInTheDocument();
    expect(screen.getByRole('progressbar')).toBeInTheDocument();
  });

  it('should render with value prop greather than maxValue without crashing', () => {
    render(<ProgressMeter label="test" maxValue={100} value={150} />);
    expect(screen.getByTestId('Checkmark2')).toBeInTheDocument();
    expect(screen.getByRole('progressbar')).toBeInTheDocument();
  });

  it('should render with hasError prop without crashing', () => {
    render(<ProgressMeter label="test" maxValue={100} value={50} hasError />);
    expect(screen.getByTestId('AlertOctagon')).toBeInTheDocument();
    expect(screen.getByRole('progressbar')).toBeInTheDocument();
  });
});
